using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Aspire.Hosting.Testing;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;
    private static DistributedApplicationTestingBuilder? s_appHost;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        s_appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await s_appHost.BuildAsync();

        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (s_appHost is not null)
        {
            await s_appHost.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var reportStore = new DiskBasedReportStore(Path.Combine("TestResults", "EvalReports"));

        return new ReportingConfiguration(evaluators, reportStore);
    }

    [TestMethod]
    public async Task ChatRespondsCoherently()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(ChatRespondsCoherently));

        var chatClient = scenario.GetChatClient(CreateChatClient());

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        // Verify no evaluator scored below threshold
        foreach (var metric in scenario.GetEvaluationResult().Metrics)
        {
            Assert.IsTrue(
                metric.Value.Rating >= EvaluationRating.Good,
                $"Metric '{metric.Key}' scored below threshold: {metric.Value.Rating}");
        }
    }

    [TestMethod]
    public async Task ChatHandlesFollowUp()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(ChatHandlesFollowUp));

        var chatClient = scenario.GetChatClient(CreateChatClient());

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire in one sentence."),
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.AddRange(response.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "Can you elaborate on its key features?"));

        response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        foreach (var metric in scenario.GetEvaluationResult().Metrics)
        {
            Assert.IsTrue(
                metric.Value.Rating >= EvaluationRating.Good,
                $"Metric '{metric.Key}' scored below threshold: {metric.Value.Rating}");
        }
    }

    private static IChatClient CreateChatClient()
    {
        var app = s_appHost!.BuildAsync().GetAwaiter().GetResult();
        var chatClient = app.Services.GetRequiredService<IChatClient>();
        return chatClient;
    }
}

